					sdfMaterial = matEntityId.ToObject() as Material;
				}
				if (sdfMaterial == null)
				{
					Shader shaderAsset = Shader.Find("Hidden/Sirenix/SdfIconShader");
					sdfMaterial = new Material(shaderAsset);
					UnityEngine.Object.DontDestroyOnLoad(sdfMaterial);
					sdfMaterial.hideFlags = HideFlags.DontUnloadUnusedAsset;
					OdinEntityId.SetSessionStateId("odin_sdf_material3", OdinEntityId.FromObject(sdfMaterial));
				}
				UnityEngine.Object.DontDestroyOnLoad(sdfMaterial);
				Shader.SetGlobalColor("_SirenixOdin_Color", new Color(1f, 1f, 1f, 1f));
				Shader.SetGlobalColor("_SirenixOdin_BgColor", new Color(0f, 0f, 0f, 0f));
				Shader.SetGlobalVector("_SirenixOdin_Uv", new Vector4(0f, 0f, 1f, 1f));
				Shader.SetGlobalFloat("_SirenixOdin_EdgeOffset", 0f);
				Shader.SetGlobalTexture("_SirenixOdin_SdfTex", SdfTexture);
				_uv = new Vector4(0f, 0f, 1f, 1f);
				_edgeOffset = 0f;
				_color = new Color(1f, 1f, 1f, 1f);
				_bgColor = new Color(0f, 0f, 0f, 0f);
			}
			else
			{
				Shader.SetGlobalTexture("_SirenixOdin_SdfTex", SdfTexture);
			}
		}

		private static void EnsureSdfTextureIsValid()
		{
			if (sdfTexture == null)
			{
				string sdfPath = SirenixAssetPaths.OdinPath + "Assets/Editor/SdfIconAtlas.png";
				sdfTexture = AssetDatabase.LoadAssetAtPath<Texture2D>(sdfPath);
				if (sdfTexture == null)
				{
					sdfMaterial = null;
					return;
				}
				sdfTexture.hideFlags = HideFlags.DontUnloadUnusedAsset;
				UnityEngine.Object.DontDestroyOnLoad(sdfTexture);
			}
		}

		public static Texture2D CreateTransparentIconTexture(SdfIconType iconType, Color color, int width, int height, int padding)
		{
			SdfIcon icon = AllIcons[(int)iconType];
			return CreateTransparentIconTexture(icon, color, default(Color), new Color(color.r, color.g, color.b, 0f), width, height, padding);
		}

		public static Texture2D CreateTransparentIconTexture(SdfIcon icon, Color color, Color bgColor, Color clearColor, int width, int height, int padding)
		{
			Texture2D tex = SdfTexture;
			if (tex == null)
			{
				return null;
			}
			if (icon.Width < icon.Height)
			{
				float ratio = (float)icon.Width / (float)icon.Height;
				int newWidth = Mathf.RoundToInt((float)width * ratio);
				width = newWidth;
			}
			else
			{
				float ratio2 = (float)icon.Height / (float)icon.Width;
				int newHeight = Mathf.RoundToInt((float)height * ratio2);
				height = newHeight;
			}
			EnsureMaterialIsValid();
			EnsureSdfTextureIsValid();
			SetColor(color);
			SetBgColor(bgColor);
			SetEdgeOffset(icon.EdgeOffset);
			SetUv(new Vector4(icon.Uv.X, icon.Uv.Y, icon.Uv.Width, icon.Uv.Height));
			RenderTexture prev = RenderTexture.active;
			RenderTexture rt = (RenderTexture.active = RenderTexture.GetTemporary(width, height, 0, RenderTextureFormat.ARGB32, RenderTextureReadWrite.Linear, 4));
			GL.Clear(clearDepth: false, clearColor: true, clearColor);
			bool prevsRGB = GL.sRGBWrite;
			GL.sRGBWrite = false;
			Graphics.Blit(null, rt, Material);
			Texture2D clone = new Texture2D(width, height, TextureFormat.ARGB32, mipChain: false, linear: false);
			clone.filterMode = FilterMode.Bilinear;
			clone.ReadPixels(new Rect(0f, 0f, width, height), 0, 0);
			clone.Apply();
			RenderTexture.active = prev;
			RenderTexture.ReleaseTemporary(rt);
			GL.sRGBWrite = prevsRGB;
			return clone;
		}

		public unsafe static void DrawIcon(Rect rect, SdfIcon icon, Color color, Color bgColor)
		{
			if (icon.Index <= 0 || Event.current.type != EventType.Repaint || rect.width <= 0f || rect.height <= 0f)
			{
				return;
			}
			Texture2D tex = SdfTexture;
			if (tex == null)
			{
				return;
			}
			rect = rect.AlignCenterXY(Math.Min(rect.width, rect.height));
			float sdfPaddingRatio = rect.width / (float)icon.Width;
			rect = rect.Expand(8f * sdfPaddingRatio);
			if (icon.Width < icon.Height)
			{
				float ratio = (float)icon.Width / (float)icon.Height;
				float newWidth = rect.width * ratio;
				rect.x += (rect.width - newWidth) * 0.5f;
				rect.width = newWidth;
			}
			else
			{
				float ratio2 = (float)icon.Height / (float)icon.Width;
				float newHeight = rect.height * ratio2;
				rect.y += (rect.height - newHeight) * 0.5f;
				rect.height = newHeight;
			}
			Rect clipRect = GUIClipInfo.VisibleRect;
			if (!rect.Overlaps(clipRect))
			{
				return;
			}
			float uvX = icon.Uv.X;
			float uvY = icon.Uv.Y;
			float uvWidth = icon.Uv.Width;
			float uvHeight = icon.Uv.Height;
			Rect clipped = rect;
			Rect unclipped = rect;
			float clipTop = clipRect.y - unclipped.y;
			if (clipTop > 0f)
			{
				float amount = clipTop / rect.height;
				uvY += icon.Uv.Height * amount;
				uvHeight -= icon.Uv.Height * amount;
				clipped.y += clipTop;
				clipped.height -= clipTop;
			}
			float clipBottom = unclipped.yMax - clipRect.yMax;
			if (clipBottom > 0f)
			{
				float amount2 = clipBottom / rect.height;
				uvHeight -= uvHeight * amount2;
				clipped.height -= clipBottom;
			}
			float clipLeft = clipRect.x - unclipped.x;
			if (clipLeft > 0f)
			{
				float amount3 = clipLeft / rect.width;
				uvX += icon.Uv.Width * amount3;
				uvWidth -= icon.Uv.Width * amount3;
				clipped.x += clipLeft;
				clipped.width -= clipLeft;
			}
			float clipRight = unclipped.xMax - clipRect.xMax;
			if (clipRight > 0f)
			{
				float amount4 = clipRight / rect.width;
				uvWidth -= uvWidth * amount4;
				clipped.width -= clipRight;
			}
			color *= GUI.color;
			clipped.x = Mathf.RoundToInt(clipped.x);
			clipped.y = Mathf.RoundToInt(clipped.y);
			clipped.width = Mathf.RoundToInt(clipped.width);
			clipped.height = Mathf.RoundToInt(clipped.height);
			if (!GUI.enabled)
			{
				color.a *= 0.4f;
			}
			EnsureMaterialIsValid();
			EnsureSdfTextureIsValid();
			SetColor(color);
			SetBgColor(bgColor);
			int w = Mathf.RoundToInt(Math.Max(rect.width, rect.height));
			if (w < uvOffsets.Length)
			{
				ulong[] uvs = uvOffsets[w];
				if (uvs != null)
				{
					ulong uvLong = uvs[icon.Index];
					Vector2 uvVec = *(Vector2*)(&uvLong);
					uvX += uvVec.x;
					uvY += uvVec.y;
				}
			}
			SetEdgeOffset(icon.EdgeOffset);
			SetUv(new Vector4(uvX, uvY, uvWidth, uvHeight));
			Graphics.DrawTexture(clipped, tex, Material);
		}

		public static void DrawIcon(Rect rect, SdfIcon icon, Color color)
		{
			DrawIcon(rect, icon, color, new Color(0f, 0f, 0f, 0f));
		}

		public static void DrawIcon(Rect rect, SdfIconType icon, Color color, Color bgColor)
		{
			DrawIcon(rect, AllIcons[(int)icon], color, bgColor);
		}

		public static void DrawIcon(Rect rect, SdfIconType icon, Color color)
		{
			DrawIcon(rect, AllIcons[(int)icon], color, new Color(0f, 0f, 0f, 0f));
		}

		public static void DrawIcon(Rect rect, SdfIconType icon)
		{
			DrawIcon(rect, AllIcons[(int)icon], EditorStyles.label.normal.textColor, new Color(0f, 0f, 0f, 0f));
		}

		public static void SetColor(Color color)
		{
			if (_color != color)
			{
				Shader.SetGlobalColor("_SirenixOdin_Color", color);
				Material.SetColor("_SirenixOdin_Color", color);
				_color = color;
			}
		}

		public static void SetBgColor(Color bgColor)
		{
			if (_bgColor != bgColor)
			{
				Shader.SetGlobalColor("_SirenixOdin_BgColor", bgColor);
				Material.SetColor("_SirenixOdin_BgColor", bgColor);
				_bgColor = bgColor;
			}
		}

		public static void SetUv(Vector4 uv)
		{
			if (_uv != uv)
			{
				Shader.SetGlobalVector("_SirenixOdin_Uv", uv);
				Material.SetVector("_SirenixOdin_Uv", uv);
				_uv = uv;
			}
		}

		public static void SetEdgeOffset(float edgeOffset)
		{
			if (_edgeOffset != edgeOffset)
			{
				Shader.SetGlobalFloat("_SirenixOdin_EdgeOffset", edgeOffset);
				Material.SetFloat("_SirenixOdin_EdgeOffset", edgeOffset);
				_edgeOffset = edgeOffset;
			}
		}
	}
